const apps = $input.all().map(i => i.json);
const leads = apps.map(a => ({
  appName: a.name,
  handle: a.handle,
  rating: a.rating,
  developerName: a.developerName,
  developerEmail: a.developerEmail,
  mentionedDomains: a.mentionedDomains || [],
  painSignalSummary: a.painSignalSummary,
  agentSummary: a.agentSummary
}));
return [{ json: { totalApps: leads.length, withDevEmail: leads.filter(l => !!l.developerEmail).length, leads } }];
